class ResetService:
    def __init__(self, accounts, mailer):
        self.accounts = accounts
        self.mailer = mailer

    def request(self, email: str) -> None:
        account = self.accounts.find_by_email(email)
        if account is None:
            return
        token = self.accounts.create_reset_token(account.id)
        self.mailer.send_password_reset(account.email, token)


